CREATE TABLE institutions (id bigserial PRIMARY KEY, name varchar(180) NOT NULL, region varchar(120) NOT NULL DEFAULT '', deleted boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE users (id bigserial PRIMARY KEY, name varchar(120) NOT NULL, email varchar(254) NOT NULL UNIQUE, password_hash varchar(100) NOT NULL, role varchar(30) NOT NULL DEFAULT 'LEARNER' CHECK(role IN ('LEARNER','INSTITUTION_ADMIN','PLATFORM_ADMIN')), language varchar(2) NOT NULL DEFAULT 'en', occupation varchar(100) NOT NULL DEFAULT '', region varchar(120) NOT NULL DEFAULT '', education varchar(120) NOT NULL DEFAULT '', income_bracket varchar(80) NOT NULL DEFAULT '', knowledge_level varchar(30) NOT NULL DEFAULT 'Unassessed', token_version integer NOT NULL DEFAULT 0, enabled boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE learner_profiles (user_id bigint PRIMARY KEY REFERENCES users(id), preferences text NOT NULL DEFAULT '', weekly_goal integer NOT NULL DEFAULT 3 CHECK(weekly_goal BETWEEN 1 AND 20), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE institution_memberships (id bigserial PRIMARY KEY, institution_id bigint NOT NULL REFERENCES institutions(id), user_id bigint NOT NULL REFERENCES users(id), UNIQUE(institution_id,user_id));
CREATE TABLE topics (id bigserial PRIMARY KEY, name varchar(120) NOT NULL UNIQUE, description text NOT NULL DEFAULT '', deleted boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE lessons (id bigserial PRIMARY KEY, title varchar(200) NOT NULL, description text NOT NULL, topic_id bigint NOT NULL REFERENCES topics(id), difficulty varchar(30) NOT NULL CHECK(difficulty IN ('Beginner','Intermediate','Advanced')), duration integer NOT NULL CHECK(duration>0), objectives text NOT NULL, content text NOT NULL, example text NOT NULL, takeaways text NOT NULL, source_url text NOT NULL DEFAULT '', deleted boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE lesson_bookmarks (user_id bigint REFERENCES users(id), lesson_id bigint REFERENCES lessons(id), created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(user_id,lesson_id));
CREATE TABLE lesson_progress (user_id bigint REFERENCES users(id), lesson_id bigint REFERENCES lessons(id), completed boolean NOT NULL DEFAULT false, last_accessed timestamptz NOT NULL DEFAULT now(), completed_at timestamptz, PRIMARY KEY(user_id,lesson_id));
CREATE TABLE assessments (id bigserial PRIMARY KEY, title varchar(200) NOT NULL, lesson_id bigint REFERENCES lessons(id), deleted boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE assessment_questions (id bigserial PRIMARY KEY, assessment_id bigint NOT NULL REFERENCES assessments(id), topic_id bigint NOT NULL REFERENCES topics(id), prompt text NOT NULL, explanation text NOT NULL, position integer NOT NULL DEFAULT 0);
CREATE TABLE assessment_options (id bigserial PRIMARY KEY, question_id bigint NOT NULL REFERENCES assessment_questions(id), label text NOT NULL, correct boolean NOT NULL DEFAULT false);
CREATE TABLE assessment_attempts (id bigserial PRIMARY KEY, user_id bigint NOT NULL REFERENCES users(id), assessment_id bigint NOT NULL REFERENCES assessments(id), score double precision NOT NULL, classification varchar(30) NOT NULL, method varchar(100) NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE assessment_responses (id bigserial PRIMARY KEY, attempt_id bigint NOT NULL REFERENCES assessment_attempts(id), question_id bigint NOT NULL REFERENCES assessment_questions(id), option_id bigint NOT NULL REFERENCES assessment_options(id), correct boolean NOT NULL, UNIQUE(attempt_id,question_id));
CREATE TABLE government_schemes (id bigserial PRIMARY KEY, title varchar(200) NOT NULL, category varchar(120) NOT NULL, region varchar(120) NOT NULL DEFAULT 'All India', beneficiaries varchar(200) NOT NULL, summary text NOT NULL, eligibility text NOT NULL, benefits text NOT NULL, documents text NOT NULL, procedure text NOT NULL, faq text NOT NULL, source_url text NOT NULL, verification varchar(100) NOT NULL DEFAULT 'Demonstration — verify current rules', deleted boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE policy_documents (id bigserial PRIMARY KEY, scheme_id bigint REFERENCES government_schemes(id), title varchar(200) NOT NULL, content text NOT NULL, source_url text NOT NULL, language varchar(2) NOT NULL DEFAULT 'en', deleted boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE scheme_bookmarks (user_id bigint REFERENCES users(id), scheme_id bigint REFERENCES government_schemes(id), created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(user_id,scheme_id));
CREATE TABLE search_history (id bigserial PRIMARY KEY, user_id bigint REFERENCES users(id), query text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE conversation_history (id bigserial PRIMARY KEY, user_id bigint NOT NULL REFERENCES users(id), question text NOT NULL, answer text NOT NULL, sources text NOT NULL, language varchar(2) NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE engagement_logs (id bigserial PRIMARY KEY, user_id bigint NOT NULL REFERENCES users(id), lesson_id bigint REFERENCES lessons(id), scheme_id bigint REFERENCES government_schemes(id), action varchar(50) NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE learner_recommendations (id bigserial PRIMARY KEY, user_id bigint NOT NULL REFERENCES users(id), lesson_id bigint NOT NULL REFERENCES lessons(id), reason text NOT NULL, method varchar(100) NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE disengagement_predictions (id bigserial PRIMARY KEY, user_id bigint NOT NULL REFERENCES users(id), risk_score double precision NOT NULL, category varchar(30) NOT NULL, method varchar(100) NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE contact_submissions (id bigserial PRIMARY KEY, name varchar(120) NOT NULL, email varchar(254) NOT NULL, message text NOT NULL, status varchar(30) NOT NULL DEFAULT 'New', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE audit_logs (id bigserial PRIMARY KEY, actor_id bigint REFERENCES users(id), action varchar(120) NOT NULL, resource varchar(100) NOT NULL, resource_id bigint, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE password_reset_tokens (token_hash varchar(64) PRIMARY KEY, user_id bigint NOT NULL REFERENCES users(id), expires_at timestamptz NOT NULL, used boolean NOT NULL DEFAULT false);
CREATE INDEX idx_engagement_user_date ON engagement_logs(user_id,created_at);
CREATE INDEX idx_attempts_user_date ON assessment_attempts(user_id,created_at);
CREATE INDEX idx_memberships_user ON institution_memberships(user_id);
CREATE INDEX idx_lessons_topic ON lessons(topic_id);
CREATE INDEX idx_predictions_user ON disengagement_predictions(user_id,created_at);
CREATE INDEX idx_conversation_user ON conversation_history(user_id,created_at);
